from abc import abstractmethod, ABCMeta

class RfSwitch(metaclass=ABCMeta):
    """
    RF switch API abstract base class.
    """

    @abstractmethod
    def connect_ports(self, port_in, port_out):
        """
        Code to connect RF switch input port to output port.
        """
        pass

    @abstractmethod
    def disconnect_ports(self, port_in, port_out):
        """
        Code to disconnect RF switch input port from output port.
        """
        pass

    @abstractmethod
    def get_port_in_status(self, port_in):
        """
        Get RF switch input port status.
        """
        pass

    @abstractmethod
    def get_port_out_status(self, port_out):
        """
        Get RF switch output port status.
        """
        pass

    @abstractmethod
    def get_connected_ports(self):
        """
        Returns currently connected ports.
        """
        pass
